import json
import os

# Load all used words from chapters 1-8 (excl 3)
used_words = set()
for path in [
    'assets/data/chapter_01_food.json',
    'assets/data/chapter_02_holiday.json',
    'assets/data/chapter_04_electronics.json',
    'assets/data/chapter_05_books.json',
    'assets/data/chapter_06_games.json',
    'assets/data/chapter_07_plants.json',
    'assets/data/chapter_08_painting.json'
]:
    if os.path.exists(path):
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        for lvl in data.get('levels', []):
            for w in lvl.get('words', []):
                used_words.add(w['word'].upper().replace(' ', '').replace('-', ''))

print(f"Total used words in prior chapters: {len(used_words)}")

