# Format & sanitize words
cleaned_words = []
seen_in_ch9 = set()

for obj in raw_words_dataset:
    raw_w = obj["word"]
    clean_w = raw_w.upper().strip().replace(" ", "").replace("-", "")
    
    if not clean_w.isalpha():
        print(f"WARNING: Invalid non-alpha word '{clean_w}'")
        continue
        
    if clean_w in used_words:
        print(f"WARNING: Word '{clean_w}' already used in prior chapters!")
        continue
        
    if clean_w in seen_in_ch9:
        print(f"WARNING: Duplicate word inside Ch9 list: '{clean_w}'")
        continue
        
    seen_in_ch9.add(clean_w)
    cleaned_words.append({
        "word": clean_w,
        "meaning": obj["meaning"],
        "example": obj["example"]
    })

print(f"Total valid unique Ch9 words: {len(cleaned_words)}")

